from datetime import datetime
from itertools import groupby
from typing import DefaultDict, List, Tuple

import cv2
import numpy as np

import utils
from psql import PsqlData, PsqlModule


def GetCameraID():
    ctrler_db = PsqlModule()
    data = ctrler_db.ReadData("cameras", ['id', 'name'],
                              'where "isAdopted"=true')
    cam_id = []
    for row in data:
        cam_id.append({"id": row[0], "name": row[1]})

    return cam_id


