def GetRawDataFromPayload(psql_data: PsqlData, bbox_obj: DefaultDict[str,
                                                                     list],
                          id_count: DefaultDict[str, DefaultDict[int, tuple]],
                          time_bound: int) -> None:

    id_in_interval = set()
    curr_max_count = defaultdict(lambda: defaultdict(int))
    curr_sample_num = defaultdict(lambda: defaultdict(int))
    timestamp = 0
    for row in psql_data:
        for event_bbox in row:
            timestamp = event_bbox['clockWall']
            single_frame_time = event_bbox['displayTimeoutMSec']
            if single_frame_time == 0: continue
            while timestamp > time_bound:
                time_bound += utils.MinStepForCount
                id_in_interval.clear()
            for bbox in event_bbox['descriptors']:
                bbox_id = bbox['trackerID']

                # prevent from exploding the count if getting old raws payload
                # filter through trackerID
                # new raws payload should not have the duplicate trackerID in one interval
                if "stationary" in bbox and bbox[
                        'stationary'] and bbox_id not in id_in_interval:
                    obj_type = bbox['objectType']
                    coord = bbox['coord']
                    bbox_obj[obj_type].append(coord)
                    curr_max_count[obj_type][time_bound] += 1
                    curr_sample_num[obj_type][time_bound] = max(
                        curr_sample_num[obj_type][time_bound],
                        utils.MinStepForCount // single_frame_time)
                    id_in_interval.add(bbox_id)

    for o_type in utils.ObjectType:
        if o_type not in curr_max_count: continue
        for time, count in curr_max_count[o_type].items():
            sample = curr_sample_num[o_type][time]
            id_count[o_type][time] = (max(id_count[o_type][time][0], count),
                                      id_count[o_type][time][1] + sample)


def GetDataFromPayload(psql_data: PsqlData,
                       bbox_obj: DefaultDict[str, list],
                       id_count: DefaultDict[str, DefaultDict[int, tuple]],
                       time_bound: int,
                       consec_cnt_th=utils.ConsecCountThreshold) -> None:
    curr_max_count = defaultdict(lambda: defaultdict(int))
    timestamp = 0
    for row in psql_data:
        for bbox in row[0]:
            timestamp = bbox['timestamp']
            if timestamp > time_bound:
                for o_type in utils.ObjectType:
                    if o_type not in curr_max_count: continue
                    _, cnt_list = zip(*sorted(curr_max_count[o_type].items(),
                                              key=lambda x: x[0]))
                    id_count[o_type][time_bound] = (GetMaxCount(
                        cnt_list, consec_cnt_th), len(cnt_list))

                curr_max_count = defaultdict(lambda: defaultdict(int))
                while timestamp > time_bound:
                    time_bound += utils.MinStepForCount

            obj_type = bbox['objectType']
            coord = bbox['coord']
            is_keep_bbox = True
            if "stationary" in bbox and bbox['stationary']:
                if bbox['level'] < utils.StationaryConfThreshold or coord[
                        2] * coord[3] < utils.StationarySizeThreshold:
                    is_keep_bbox = False

            if is_keep_bbox:
                bbox_obj[obj_type].append(coord)
            curr_max_count[obj_type][timestamp] += 1

    while timestamp > time_bound:
        time_bound += utils.MinStepForCount
    for o_type in utils.ObjectType:
        if o_type not in curr_max_count: continue
        _, cnt_list = zip(
            *sorted(curr_max_count[o_type].items(), key=lambda x: x[0]))
        id_count[o_type][time_bound] = (GetMaxCount(cnt_list, consec_cnt_th),
                                        len(cnt_list))


def GetEventDataWithTime(cam_id: str,
                         start_time: int,
                         end_time: int,
                         is_get_raws: bool = True) -> Tuple[dict, dict, dict]:

    ctrler_db = PsqlModule()
    command = """SELECT payload FROM events e INNER JOIN "smartDetectTracks" s ON s."eventId"=e.id \
        WHERE e."type"='smartDetectZone' AND e."cameraId"='{0}' AND e."end" between {1} and {2} ORDER BY e."end";""".format(
        cam_id, start_time, end_time)

    bboxes_within_interval = defaultdict(list)
    id_count_within_interval = defaultdict(lambda: defaultdict(lambda: (0, 0)))

    # Get data from events
    event_psql_data = ctrler_db.ReadDataWithRawCommand(command)
    GetDataFromPayload(event_psql_data, bboxes_within_interval,
                       id_count_within_interval,
                       start_time + utils.MinStepForCount)
    # Get data from raws (stationary objects)
    if is_get_raws:
        command = """SELECT payload FROM "smartDetectRaws" WHERE "cameraId"='{0}' \
            AND "timestamp" between {1} and {2} ORDER BY "timestamp";""".format(
            cam_id, start_time, end_time)
        raw_psql_data = ctrler_db.ReadDataWithRawCommand(command)

        GetRawDataFromPayload(raw_psql_data, bboxes_within_interval,
                              id_count_within_interval,
                              start_time + utils.MinStepForCount)

    return bboxes_within_interval, id_count_within_interval


def CreateGaussKernel(w: int, h: int, kernel_cache: dict) -> np.array:
    if (w, h) in kernel_cache:
        gauss = kernel_cache[(w, h)]
    elif (h, w) in kernel_cache:
        gauss = np.transpose(kernel_cache[(h, w)])
    else:
        gauss_l = []
        for l in [w, h]:
            if l in kernel_cache:
                gauss_l.append(kernel_cache[l])
            else:
                # gauss_l.append(GetGaussianKernel(int(l), l / 8.0))
                gauss_l.append(cv2.getGaussianKernel(int(l), l / 8.0))
                kernel_cache[l] = gauss_l[-1]

        gauss_x, gauss_y = gauss_l
        gauss = np.matmul(gauss_y, np.transpose(gauss_x))

        # kernel_cache[(w, h)] = Normalize(gauss, 0.0, 1.0)
        kernel_cache[(w, h)] = cv2.normalize(gauss, gauss, 0.0, 1.0,
                                             cv2.NORM_MINMAX)
    return gauss


def MakeRawHeatmap(bboxes_per_step: List[dict],
                   id_count_per_step: List[dict]) -> Tuple[np.array, np.array]:
    img_h, img_w = utils.HeatmapSize

    kernel_cache = {}
    raw_heatmap_per_step = np.zeros(
        (img_h, img_w, utils.NumDetectTypes, len(bboxes_per_step)),
        dtype=np.float32)
    sample_num_per_step = np.zeros(
        (utils.NumDetectTypes, len(bboxes_per_step)), dtype=np.int32)

    for step_num, (bboxes_all_types, id_count) in enumerate(
            zip(bboxes_per_step, id_count_per_step)):
        for obj_type, bboxes in bboxes_all_types.items():
            if obj_type not in utils.ObjectIndex: continue
            obj_idx = utils.ObjectIndex[obj_type]
            sample_num_per_step[obj_idx, step_num] = sum(
                map(lambda x: x[1], id_count[obj_type].values()))
            for bbox in bboxes:
                bbox[0] = max(int(bbox[0] / 1000 * img_w), 0)
                bbox[1] = max(int(bbox[1] / 1000 * img_h), 0)
                bbox[2] = min(int(bbox[2] / 1000 * img_w), img_w - bbox[0])
                bbox[3] = min(int(bbox[3] / 1000 * img_h), img_h - bbox[1])

                if bbox[2] <= 0 or bbox[3] <= 0: continue

                gauss = CreateGaussKernel(bbox[2], bbox[3], kernel_cache)
                raw_heatmap_per_step[bbox[1]:bbox[1] + bbox[3],
                                     bbox[0]:bbox[0] + bbox[2], obj_idx,
                                     step_num] += gauss
        if step_num != 0:
            raw_heatmap_per_step[:, :, :,
                                 step_num] += raw_heatmap_per_step[:, :, :,
                                                                   step_num -
                                                                   1]
            sample_num_per_step[:,
                                step_num] += sample_num_per_step[:,
                                                                 step_num - 1]

    return raw_heatmap_per_step, sample_num_per_step


def GetMaxCount(cnt_list: List[int],
                consec_cnt_th: int = utils.ConsecCountThreshold) -> int:
    consecutive_frame_per_count = [(cnt[0], len(list(cnt[1])))
                                   for cnt in groupby(cnt_list)]

    consecutive_frame_per_count = list(
        filter(lambda x: x[1] >= consec_cnt_th, consecutive_frame_per_count))

    if not consecutive_frame_per_count: return 0

    consecutive_frame_per_count.sort(reverse=True)

    return consecutive_frame_per_count[0][0]


def MakeMaxCountArray(
        id_count_per_step: List[dict],
        timestamps_per_step: List[int],
        timestep: int = utils.MinStep) -> Tuple[np.array, np.array]:
    time_split = list(
        map(
            lambda x: [
                x - t if t >= 0 else x
                for t in range(timestep - utils.MinStepForCount, -utils.
                               MinStepForCount, -utils.MinStepForCount)
            ], timestamps_per_step))

    max_id_count = np.zeros((len(
        utils.ObjectType), len(id_count_per_step), len(time_split[0]) + 1),
                            dtype=np.int32)

    for step_num, id_count in enumerate(id_count_per_step):
        for obj_type, ts_count in id_count.items():
            if obj_type not in utils.ObjectIndex: continue
            obj_idx = utils.ObjectIndex[obj_type]
            ts_list, cnt_list = zip(
                *sorted(ts_count.items(), key=lambda x: x[0]))
            time_idx = [0] + [
                bisect.bisect_right(ts_list, t) for t in time_split[step_num]
            ]
            count = [
                max(map(lambda x: x[0], cnt_list[time_idx[i - 1]:time_idx[i]]))
                if time_idx[i - 1] < time_idx[i] else 0
                for i in range(1, len(time_idx))
            ]
            count += [max(count)]
            max_id_count[obj_idx, step_num, :] = count

    return max_id_count, np.array(time_split, dtype=np.int64)


def SaveAnalyticData(cam_id: int,
                     bboxes_per_step: List[dict],
                     id_count_per_step: List[dict],
                     timestamps_per_step: List[int],
                     endtime: int,
                     output_dir: int,
                     custom_step=utils.MinStep) -> None:

    raw_heatmap_per_step, sample_num_per_step = MakeRawHeatmap(
        bboxes_per_step, id_count_per_step)
    max_id_count, time_split = MakeMaxCountArray(id_count_per_step,
                                                 timestamps_per_step,
                                                 timestep=custom_step)
    os.makedirs(output_dir, exist_ok=True)
    analytic_data_path = os.path.join(
        output_dir, "{}_analytic_data_{}.npz".format(cam_id, endtime))
    np.savez_compressed(analytic_data_path,
                        raw_heatmap=raw_heatmap_per_step,
                        sample_num=sample_num_per_step,
                        timestamp=time_split,
                        max_id_count=max_id_count)

    print("Save analytic data npy to", analytic_data_path)


def Main():
    parser = argparse.ArgumentParser(
        "Save smart detect analytic data from controller database to npz")

    parser.add_argument(
        "-id",
        dest="cam_id",
        nargs='+',
        help='target camera id to get analytic data, multiple ids are allowed',
        type=str)
    parser.add_argument(
        "-name",
        dest='cam_name',
        nargs='+',
        help=
        'target camera name to get analytic data, multiple names are allowed',
        type=str)
    parser.add_argument("-out",
                        dest='output_dir',
                        help='output directory to save analytic data',
                        type=str)
    parser.add_argument('-s',
                        dest='start_time',
                        help='start timestamp (ms) of desired interval',
                        type=int)
    parser.add_argument('-e',
                        dest='end_time',
                        help='end timestamp (ms) of desired interval',
                        type=int)

    args = parser.parse_args()

    utils.LimitMemUsage(utils.VirtualMemUsageLimit)

    cam_under_ctrl = GetCameraID()
    cam_designate = set()
    if args.cam_id:
        cam_id = set(args.cam_id)
        cam_candidate_id = set(map(lambda x: x['id'], cam_under_ctrl))
        cam_designate |= cam_id & cam_candidate_id
        cam_not_found = cam_id - cam_designate
        if cam_not_found:
            print("WARN: {} is not found. skipped.".format(cam_not_found))

    if args.cam_name:
        cam_name = set(args.cam_name)
        cam_candidate_id = set()
        cam_candidate_name = set()
        cam_not_found = set()
        for cam_candidate in cam_under_ctrl:
            if cam_candidate['name'] in cam_name:
                cam_candidate_id.add(cam_candidate['id'])
                cam_candidate_name.add(cam_candidate['name'])

        cam_not_found = cam_name - cam_candidate_name
        cam_designate |= cam_candidate_id
        if cam_not_found:
            print("WARN: {} is not found. skipped.".format(cam_not_found))

    if not args.cam_id and not args.cam_name:
        cam_designate = set(map(lambda x: x['id'], cam_under_ctrl))

    start_time = 0
    end_time = int(datetime.timestamp(datetime.now())) * 1000
    if args.start_time:
        start_time = args.start_time
    if args.end_time:
        end_time = args.end_time

    start_time = utils.RoundTimeToNearestMin(args.start_time,
                                             30,
                                             return_ts=True)
    end_time = utils.RoundTimeToNearestMin(args.end_time, 30, return_ts=True)

    if end_time <= start_time:
        raise ValueError("End time is earlier than Start time")

    if end_time - start_time > utils.SaveNPZTimeRangeLimit:
        raise ValueError("Got too wide time range(> 2 days)! Stopped.")

    for cam_id in cam_designate:
        print(cam_id)
        bboxes_per_step = []
        id_count_per_step = []
        timestamps_per_step = []
        for start in range(start_time, end_time, utils.MinStep):
            end = start + utils.MinStep if start + utils.MinStep <= end_time else end_time
            bboxes_within_interval, id_count_within_interval = GetEventDataWithTime(
                cam_id, start, end)
            timestamps_per_step.append(end)
            bboxes_per_step.append(bboxes_within_interval)
            id_count_per_step.append(id_count_within_interval)

        SaveAnalyticData(cam_id, bboxes_per_step, id_count_per_step,
                         timestamps_per_step, end_time, args.output_dir)


if __name__ == "__main__":
    Main()
